head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "JLDFIL51000N2_MENU";

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — param.page, listProcsStatCd, gongMo

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_conds();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil51000n2_menu.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_page", fn: function(){ return ((dma_pageContext.get("page") ?? "") !=='20' && (dma_pageContext.get("page") ?? "") !=='30' && (dma_pageContext.get("page") ?? "") !=='40' && (dma_pageContext.get("page") ?? "") !=='50' && (dma_pageContext.get("page") ?? "") !=='60'); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_changePage2_onclick
 * @description 「기업일반정보」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_changePage2_onclick = function(e){
    try {
        changePage2(1,1,(String(((dma_pageContext.get("listProcsStatCd") ?? "")) == null ? '' : ((dma_pageContext.get("listProcsStatCd") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("listProcsStatCd") ?? "")) == null ? '' : ((dma_pageContext.get("listProcsStatCd") ?? "")))),(String(((dma_pageContext.get("gongMo") ?? "")) == null ? '' : ((dma_pageContext.get("gongMo") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("gongMo") ?? "")) == null ? '' : ((dma_pageContext.get("gongMo") ?? "")))))

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil51000n2_menu.btn_changePage2_onclick' }); }
};

